const range = $('Week range').first().json;
const commitItems = $('GitHub Commits').first().json.items || [];
const prItems = $('GitHub PRs').first().json.items || [];

const commits = commitItems.map(c => ({
  repo: c.repository.full_name,
  day: c.commit.author.date.slice(0, 10),
  time: c.commit.author.date.slice(11, 16),
  message: c.commit.message.split('\n')[0],
  sha: c.sha.slice(0, 7),
}));

const prs = prItems.map(p => ({
  repo: p.repository_url.split('/').slice(-2).join('/'),
  number: p.number,
  title: p.title,
  state: p.state,
  created_day: p.created_at.slice(0, 10),
  updated_day: p.updated_at.slice(0, 10),
}));

return [{
  json: {
    since: range.since,
    until: range.until,
    commit_count: commits.length,
    pr_count: prs.length,
    commits,
    prs,
  },
}];

