        }
      }
    },
    required: ['entries']
  },
  messages: [
    {
      role: 'system',
      content: 'You are an assistant that prepares a developer weekly timesheet from GitHub activity. Rules: (1) Create ONE entry per project (repo) per day that has activity. (2) Ignore merge commits (messages starting with "Merge"). (3) description: one short English sentence summarizing the real work done that day on that project. (4) estimated_hours: between 0.5 and 8, in steps of 0.5, based on the number and size of the changes. (5) date format YYYY-MM-DD, only dates present in the activity. (6) Never invent work that is not in the data. Return only JSON.'
    },
    {
      role: 'user',
      content: 'GitHub activity from ' + $json.since + ' to ' + $json.until + ':\n' + JSON.stringify({ commits: $json.commits, prs: $json.prs })
    }
  ]
}) }}

parameters.jsCode:
const activity = $('Prepare activity').first().json;
const raw = $input.first().json.message?.content ?? '';

// 0. Parse the LLM answer
let entries;
try {
  entries = JSON.parse(raw).entries;
} catch (e) {
  throw new Error('LLM did not return valid JSON: ' + raw.slice(0, 200));
}
if (!Array.isArray(entries)) throw new Error('LLM JSON has no "entries" array');

const warnings = [];
const inRange = d => d >= activity.since && d <= activity.until;

// 1. Normalize, reject invalid dates or durations
const valid = [];
for (const e of entries) {
  const date = String(e.date || '').slice(0, 10);
  const hours = Math.round(Number(e.estimated_hours) * 2) / 2;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !inRange(date)) {
    warnings.push(`Rejected entry with invalid date "${e.date}" (${e.project})`);
    continue;
  }
  if (!(hours > 0)) {
    warnings.push(`Rejected entry with invalid duration (${e.project}, ${date})`);
    continue;
  }
  valid.push({
    project: String(e.project).trim(),
    date,
    description: String(e.description).trim(),
    estimated_hours: Math.min(hours, 8),
  });
}

// 2. Duplicates: same project + same date -> merge
const byKey = new Map();
for (const e of valid) {
  const key = e.project + '|' + e.date;
  if (byKey.has(key)) {
    const prev = byKey.get(key);
    warnings.push(`Duplicate entry merged: ${e.project} on ${e.date}`);
    prev.estimated_hours = Math.min(prev.estimated_hours + e.estimated_hours, 8);
    if (prev.description !== e.description) prev.description += ' ' + e.description;
  } else {
    byKey.set(key, { ...e });
  }
}
const finalEntries = [...byKey.values()].sort(
  (a, b) => a.date.localeCompare(b.date) || a.project.localeCompare(b.project)
);

// 3. Days with commits but no timesheet entry
const activityKeys = new Set(
  activity.commits
    .filter(c => !c.message.startsWith('Merge'))
    .map(c => c.repo + '|' + c.day)
);
for (const k of activityKeys) {
  if (!byKey.has(k)) {
    const [repo, day] = k.split('|');
    warnings.push(`Activity without entry: ${repo} on ${day}`);
  }
}

// 4. Total hours per day
const hoursPerDay = {};
for (const e of finalEntries) {
  hoursPerDay[e.date] = (hoursPerDay[e.date] || 0) + e.estimated_hours;
}
for (const [d, h] of Object.entries(hoursPerDay)) {
  if (h > 10) warnings.push(`More than 10h on ${d} (${h}h)`);
}

// 5. Weekdays (Mon-Fri) with no activity
const emptyWeekdays = [];
const end = new Date(activity.until + 'T00:00:00Z');
for (let d = new Date(activity.since + 'T00:00:00Z'); d <= end; d.setUTCDate(d.getUTCDate() + 1)) {
  const iso = d.toISOString().slice(0, 10);
  const wd = d.getUTCDay();
  if (wd >= 1 && wd <= 5 && !hoursPerDay[iso]) emptyWeekdays.push(iso);
}

const totalHours = finalEntries.reduce((s, e) => s + e.estimated_hours, 0);

return [{
  json: {
    since: activity.since,
    until: activity.until,
    entry_count: finalEntries.length,
    total_hours: totalHours,
    hours_per_day: hoursPerDay,
    empty_weekdays: emptyWeekdays,
    warnings,
    entries: finalEntries,
  },
}];
